action.code:
size_t bit_idx = 0;
size_t group_idx = 0;
const size_t group_size = sizeof(bitmap_t) * 8;
const size_t total_bits = binfo->nbits;

while (group_idx * group_size < total_bits) {
    bitmap_t group = bitmap[group_idx];
    if (~group != 0) {
        size_t offset = std::countr_one(group);
        bit_idx = group_idx * group_size + offset;
        if (bit_idx >= total_bits) break;

        bitmap_t mask = bitmap_t(1) << offset;
        bitmap_t expected = group;
        if (bitmap[group_idx].compare_exchange_strong(expected, expected | mask)) {
            return bit_idx;
        }
        continue;
    }
    ++group_idx;
}
return static_cast<size_t>(-1);
// END_CODE

